// Fechas visibles sin cambiar ISO en almacenamiento o peticiones.
function gmpDate(value){return String(value??'').replace(/(?<![0-9])([0-9]{4})-([0-9]{2})-([0-9]{2})(?:T([0-9]{2}:[0-9]{2}(?::[0-9]{2})?)(?:[.][0-9]+)?(?:Z|[+-][0-9]{2}:[0-9]{2})?)?(?![0-9])/g,(_,y,m,d,t)=>`${d}/${m}/${y}${t?' '+t:''}`);}
function gmpDateISO(value){const s=String(value??'').trim();if(!s)return '';let m=s.match(/^([0-9]{2})\/([0-9]{2})\/([0-9]{4})$/);if(!m)throw Error('Usa la fecha dd/mm/yyyy.');const iso=`${m[3]}-${m[2]}-${m[1]}`,d=new Date(iso+'T12:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==iso)throw Error('La fecha no es válida. Usa dd/mm/yyyy.');return iso;}
function gmpReadDate(id){return gmpDateISO(document.getElementById(id).value);}
function gmpTax(rate){return Number(rate)===8?'IEPS':Number(rate)===16?'IVA':'Sin IVA';}

function gmpInstallCalendars(root=document){for(const field of root.querySelectorAll('input[placeholder="dd/mm/yyyy"]')){if(field.dataset.gmpCalendar){const old=field.parentElement.querySelector('.gmp-date-picker');if(old&&old.disabled!==(field.disabled||field.readOnly))old.disabled=field.disabled||field.readOnly;continue;}field.dataset.gmpCalendar='1';const wrap=document.createElement('span');wrap.className='gmp-date-wrap';field.before(wrap);wrap.append(field);const pick=document.createElement('input');pick.type='date';pick.disabled=field.disabled||field.readOnly;pick.className='gmp-date-picker';pick.setAttribute('aria-label','Seleccionar '+(field.closest('label')?.childNodes[0]?.textContent?.trim()||'fecha'));pick.title='Abrir calendario';const icon=document.createElement('span');icon.className='gmp-date-icon';icon.textContent='▦';icon.setAttribute('aria-hidden','true');wrap.append(icon,pick);pick.addEventListener('pointerdown',()=>{try{pick.value=gmpDateISO(field.value);}catch{pick.value='';}});pick.onchange=()=>{field.value=gmpDate(pick.value);field.dispatchEvent(new Event('input',{bubbles:true}));field.dispatchEvent(new Event('change',{bubbles:true}));};field.addEventListener('input',()=>{try{pick.value=gmpDateISO(field.value);}catch{pick.value='';}});}}
if(typeof document!=='undefined'){const dateStyle=document.createElement('style');dateStyle.textContent='.gmp-date-wrap{display:flex;position:relative;width:100%;align-items:center}.gmp-date-wrap>input:first-child{width:100%;padding-right:42px}.gmp-date-icon{position:absolute;right:10px;font-size:24px;color:#017e84;pointer-events:none}.gmp-date-picker{position:absolute!important;right:0;width:40px!important;height:100%;opacity:0;cursor:pointer;padding:0!important}.gmp-date-picker::-webkit-calendar-picker-indicator{position:absolute;inset:0;width:100%;height:100%;cursor:pointer}';document.head.append(dateStyle);gmpInstallCalendars();new MutationObserver(()=>gmpInstallCalendars()).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['disabled','readonly']});}

// getRandomValues funciona también por HTTP en IP local, Radmin y ZeroTier.
// La clave evita duplicar un guardado/cobro cuando se reintenta la misma solicitud.
function commercialKey(){
 const bytes=new Uint8Array(16);
 globalThis.crypto.getRandomValues(bytes);
 return Array.from(bytes,value=>value.toString(16).padStart(2,'0')).join('');
}

const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),cash=v=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(Number(v)||0);
