async function api(action,data=null,query={}){const url='/api/comercial/'+action+'?'+new URLSearchParams({canal:channel,empresa:company,...query});let response;try{response=await fetch(data===null?url:'/api/comercial/'+action,{cache:'no-store',...(data===null?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':me.csrf},body:JSON.stringify({canal:channel,...data})})});}catch{throw Error('No se pudo conectar con el servidor. Revisa la IP y el puerto, y vuelve a intentar.');}if(response.status===401){location.assign('/');throw Error('La sesión expiró.');}const type=response.headers.get('content-type')||'';const result=type.includes('application/json')?await response.json():await response.blob();if(!response.ok)throw Error(result.error||'No se pudo completar la operación.');return result;}
function error(e){$('error').textContent=e.message||String(e);}
function notice(v){$('error').textContent='';$('notice').textContent=v;}
async function run(task){if(busy)return;busy=true;$('save').disabled=true;try{await task();}catch(e){error(e);}finally{busy=false;$('save').disabled=!meta?.puedeOperar;}}
function options(items,selected=''){return items.map(([v,n])=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(n)}</option>`).join('');}
function table(headers,rows){return `<table><thead><tr>${headers.map(h=>'<th>'+esc(h)+'</th>').join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}">Sin registros</td></tr>`}</tbody></table>`;}
function button(text,action,id='',extra=''){return `<button type="button" data-action="${action}" data-id="${esc(id)}" ${extra}>${esc(text)}</button>`;}
function field(name,label,value='',type='text',required=false){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="700" ${type==='number'?'step="any" min="0"':''}></label>`;}
function checks(name,values,selected){return `<div class="checks">${values.map(([v,n])=>`<label class="check"><input type="checkbox" name="${name}" value="${esc(v)}" ${selected.map(String).includes(String(v))?'checked':''}>${esc(n)}</label>`).join('')}</div>`;}
