function renderProductCatalog(){if(!productCatalogData)return;const q=$('productAdminSearch').value.toUpperCase(),ch=$('productAdminChannel').value,pendingOnly=$('productAdminPending').value;const pending=p=>p.iva===null||p.institucional!==false&&p.precios.PUBLICO===undefined||p.expendio&&p.precios.RUTA===undefined&&p.precios.DESPACHO===undefined;const rows=productCatalogData.productos.filter(p=>(!q||(p.sku+' '+p.nombre).toUpperCase().includes(q))&&(!ch||productChannels(p).includes(ch))&&(!pendingOnly||pending(p)));$('productAdminRows').innerHTML=table(['SKU','Descripción','Canales','Unidad','Impuesto','Público','Ruta','Despacho','Estado','Acciones'],rows.map(p=>[esc(p.sku),esc(p.nombre),productChannels(p).map(c=>channelNames[c]).join(' / '),esc(p.unidad),p.iva===null?'PENDIENTE':gmpTax(p.iva)+' '+esc(p.iva)+'%',...['PUBLICO','RUTA','DESPACHO'].map(k=>p.precios[k]===undefined?'—':cash(p.precios[k])),!p.activo?'Inactivo':pending(p)?'Datos pendientes':'Activo',meta.puedeConfigurar?button('Editar','product-edit',p.sku):'']));}
