const filterNavigate=navigate;navigate=async function(value){customerFilters();$('reportDateFieldLabel').hidden=pos;document.querySelectorAll('.institutional-date').forEach(el=>el.hidden=pos);return filterNavigate(value);};

const priceActions=actions;actions=async function(action,id){if(action==='prices-layout')return downloadCatalog('precios/layout','Layout_Precios_Clientes_GMP.xlsx');if(action!=='prices-import')return priceActions(action,id);let reviewed=null;const capturedCompany=company;editor('Precios masivos por cliente','<label>Archivo PRECIOS (.xlsx o .csv)<input id="pricesFile" type="file" accept=".xlsx,.csv" required></label><button id="pricesReview" type="button">Revisar precios</button><output id="pricesResult"></output><div id="pricesDetail" class="table-wrap wide"></div><p>Usa código de cliente y SKU. Puedes llenar precio con impuesto o antes de impuesto. Si llenas ambos, deben coincidir. Se aplican los impuestos del maestro y se conservan los demás precios.</p>',async()=>{if(!reviewed||company!==capturedCompany)throw Error('Revisa el archivo para esta razón social antes de guardar.');const r=await api('precios/importar',reviewed);await configuration();notice(r.precios+' precios por cliente actualizados.');});$('pricesFile').onchange=()=>{reviewed=null;$('pricesResult').textContent='';};$('pricesReview').onclick=async()=>{try{const file=$('pricesFile').files[0];if(!file)throw Error('Selecciona el archivo.');const upload={empresa:capturedCompany,contenido:await asBase64(file)};const r=await api('precios/importar',{...upload,revisar:true});reviewed={...upload,huellaActual:r.huellaActual};$('pricesDetail').innerHTML=table(['Cliente','SKU','Impuesto','Antes de impuesto','Con impuesto'],r.detalle.slice(0,100).map(p=>[esc(p.codigoCliente),esc(p.sku),esc(p.tipoImpuesto)+' '+esc(p.tasa)+'%',cash(p.precioAntesImpuesto),cash(p.precio)]));$('pricesResult').textContent=r.precios+' precios validados. Impuestos obtenidos del maestro. Pulsa Guardar para aplicarlos.';}catch(e){reviewed=null;$('pricesResult').textContent=e.message;}};};

const beforeOrderLock=renderCart;renderCart=function(){beforeOrderLock();if(pos)return;const locked=!!current&&(!!current.bloqueado||meta?.soloCaptura||current.estado==='CANCELADO');for(const id of ['branch','customer','kind','terms','observations','orderDate','deliveryDate','optionalCustomer'])$(id).disabled=locked;document.querySelectorAll('#lines input,#lines select,#lines [data-action="remove"]').forEach(el=>{el.disabled=locked||meta?.soloCaptura&&['precio','descuento'].includes(el.dataset.key);});$('save').disabled=locked||!meta?.puedeOperar;$('saveTop').hidden=locked;$('confirmOrder').hidden=locked||!current||current.tipo!=='PRESUPUESTO';$('toggleOrderLock').hidden=!current||!meta?.puedeDesbloquear||current.estado==='CANCELADO';$('toggleOrderLock').textContent=current?.bloqueado?'Desbloquear pedido':'Bloquear pedido';};
$('toggleOrderLock').onclick=()=>run(async()=>{const r=await api('pedidos/bloqueo',{id:current.id,revision:current.revision,bloqueado:!current.bloqueado});current=r.documento;renderCart();notice(current.bloqueado?'Documento bloqueado.':'Documento desbloqueado.');});
const beforeRestrictedNavigate=navigate;navigate=async function(value){if(meta?.soloCaptura){for(const el of document.querySelectorAll('[data-page]'))el.hidden=!['operacion','presupuestos','pedidos'].includes(el.dataset.page);$('newCustomer').hidden=true;$('settingsNav').hidden=true;if(!['operacion','presupuestos','pedidos','documentos'].includes(value))throw Error('Este perfil solo permite capturar y consultar sus documentos.');}return beforeRestrictedNavigate(value);};

const bulkTemplateActions=actions;actions=async function(action,id){if(action==='templates-layout')return downloadCatalog('plantillas/layout','Layout_Plantillas_Clientes_GMP_ERP.xlsx');if(action!=='templates-import')return bulkTemplateActions(action,id);let upload=null;const companyAtOpen=company;editor('Cargar plantillas de clientes','<label>Archivo PLANTILLAS_CLIENTES<input id="customerTemplatesFile" type="file" accept=".xlsx,.csv"></label><label class="check"><input id="customerTemplatesUpdate" type="checkbox">Actualizar plantillas con el mismo cliente y nombre</label><button id="customerTemplatesReview" type="button">Revisar</button><output id="customerTemplatesResult"></output>',async()=>{if(!upload||company!==companyAtOpen)throw Error('Revisa la carga para esta razón social.');const r=await api('plantillas/importar',upload);await loadTemplates();notice(r.nuevas+' plantillas nuevas; '+r.actualizadas+' actualizadas.');});const clear=()=>{upload=null;};$('customerTemplatesFile').onchange=clear;$('customerTemplatesUpdate').onchange=clear;$('customerTemplatesReview').onclick=async()=>{try{const file=$('customerTemplatesFile').files[0];if(!file)throw Error('Selecciona archivo.');const data={empresa:companyAtOpen,contenido:await asBase64(file),actualizar:$('customerTemplatesUpdate').checked};const r=await api('plantillas/importar',{...data,revisar:true});upload={...data,huellaActual:r.huellaActual};$('customerTemplatesResult').textContent=r.nuevas+' nuevas · '+r.actualizadas+' actualizadas · '+r.omitidas+' conservadas.';}catch(e){upload=null;$('customerTemplatesResult').textContent=e.message;}};};

let institutionalCancelRows=[];const beforeInstitutionalHistory=loadDocuments;loadDocuments=async function(){await beforeInstitutionalHistory();$('instCancellationPanel').hidden=pos;if(pos)return;institutionalCancelRows=(await api('pedidos/cancelaciones')).solicitudes;$('instCancellations').innerHTML=table(['Solicitud','Pedido / presupuesto','Motivo','Estado','Resolución','Acciones'],institutionalCancelRows.map(s=>[esc(s.folio),esc(s.folioVenta),esc(s.motivo),esc(s.estado),esc(s.resueltoPor||'')+(s.fechaResolucion?'<small>'+esc(gmpDate(s.fechaResolucion))+'</small>':''),meta.puedeAutorizarCancelacionInstitucional&&s.estado==='PENDIENTE'?button('Aprobar','inst-cancel-approve',s.id)+button('Rechazar','inst-cancel-reject',s.id,'class="secondary"'):'']));};
const beforeInstitutionalCancelActions=actions;actions=async function(action,id){if(action==='inst-cancel-request'){const doc=await api('documento',null,{id});editor('Solicitar cancelación de '+doc.folio,'<label class="wide">Motivo<textarea name="motivo" maxlength="3000" rows="5" required></textarea></label><p>La cancelación requiere aprobación de Gerencia, AUXTI o Superadministrador.</p>',async f=>{await api('pedidos/cancelacion/solicitar',{id:doc.id,revision:doc.revision,motivo:f.get('motivo')});await loadDocuments();notice('Solicitud enviada a autorización. El documento sigue vigente hasta que se apruebe.');});return;}
if(action==='inst-cancel-approve'||action==='inst-cancel-reject'){const s=institutionalCancelRows.find(s=>s.id===id);editor((action==='inst-cancel-approve'?'Aprobar':'Rechazar')+' cancelación '+s.folio,'<p>'+esc(s.folioVenta)+' · '+esc(s.motivo)+'</p><label class="wide">Comentario de resolución<textarea name="comentario" maxlength="3000" rows="4"></textarea></label>',async f=>{await api('pedidos/cancelacion/resolver',{id:s.id,revision:s.revision,aprobar:action==='inst-cancel-approve',comentario:f.get('comentario')});await loadDocuments();notice('Solicitud resuelta y registrada.');});return;}return beforeInstitutionalCancelActions(action,id);};
const beforeLockedAdd=addProduct;addProduct=async function(id){if(!pos&&current&&(current.bloqueado||meta.soloCaptura))throw Error('Este documento no admite cambios. Crea uno nuevo o solicita el desbloqueo.');return beforeLockedAdd(id);};

if(meta&&company)void run(()=>navigate(page));
